    toggleEditSupplierFields(supplierType) {
        const codeField = document.getElementById('edit-supplier-code-field');
        const taxField = document.getElementById('edit-supplier-tax-field');
        const legalFields = document.getElementById('edit-legal-info-fields');
        const bankSection = document.getElementById('edit-bank-info-section');
        const codeInput = document.querySelector('input[name="supplierCode"]');

        if (supplierType === 'doanh-nghiep') {
            codeField.style.display = 'block';
            taxField.style.display = 'block';
            legalFields.style.display = 'grid';
            bankSection.style.display = 'block';
            if (codeInput) codeInput.required = true;
        } else {
            codeField.style.display = 'none';
            taxField.style.display = 'none';
            legalFields.style.display = 'none';
            bankSection.style.display = 'none';
            if (codeInput) {
                codeInput.required = false;
                codeInput.value = '';
            }
            // Clear business fields
            const fieldsToReset = ['taxCode', 'legalRepresentative', 'contactPosition', 'bankAccount', 'bankName', 'bankBranch'];
            fieldsToReset.forEach(field => {
                const input = document.querySelector(`input[name="${field}"]`);
                if (input) input.value = '';
            });
        }
    }

    updateSupplier(event, index) {
        event.preventDefault();
        const form = event.target;
        const formData = new FormData(form);

        this.demoData.suppliers[index] = {
            ...this.demoData.suppliers[index],
            name: formData.get('name'),
            type: formData.get('type'),
            supplierCode: formData.get('supplierCode') || '',
            phone: formData.get('phone'),
            email: formData.get('email') || '',
            address: formData.get('address') || '',
            taxCode: formData.get('taxCode') || '',
            legalRepresentative: formData.get('legalRepresentative') || '',
            contactPosition: formData.get('contactPosition') || '',
            bankAccount: formData.get('bankAccount') || '',
            bankName: formData.get('bankName') || '',
            bankBranch: formData.get('bankBranch') || '',
            notes: formData.get('notes') || ''
        };

        this.saveToLocalStorage();
        this.showNotification(`Đã cập nhật nhà cung cấp ${this.demoData.suppliers[index].name}`, 'success');
        this.loadPage('suppliers');
        const modal = form.closest("div[style*=\"fixed\"]"); if (modal) modal.remove();
    }

    toggleSupplierSearch() {
        const box = document.getElementById('suppliers-search-box');
        if (box) {
            box.style.display = box.style.display === 'none' ? 'block' : 'none';
            if (box.style.display === 'block') {
                const inp = document.getElementById('suppliers-search-input');
                if (inp) { inp.focus(); }
            }
        }
    }
    setSuppliersSearch(val) {
        this.suppliersSearchQuery = val || '';
        this.loadPage('suppliers');
    }
    toggleSuppliersSelectAll(checked) {
        const q = (this.suppliersSearchQuery || '').trim().toLowerCase();
        let list = this.demoData.suppliers || [];
        if (q) {
            const nq = this.removeAccents(q);
            list = list.filter(s => {
                const n = this.removeAccents((s.name || '').toLowerCase());
                const p = this.removeAccents((s.phone || '').toLowerCase());
                const a = this.removeAccents((s.address || '').toLowerCase());
                const e = this.removeAccents((s.email || '').toLowerCase());
                return n.includes(nq) || p.includes(nq) || a.includes(nq) || e.includes(nq);
            });
        }
        list.forEach(s => { if (checked) this.selectedSupplierIds.add(s.id); else this.selectedSupplierIds.delete(s.id); });
        this.updateSuppliersSelectionUI();
    }
    toggleSupplierSelect(id, checked) {
        if (checked) this.selectedSupplierIds.add(id); else this.selectedSupplierIds.delete(id);
        this.updateSuppliersSelectionUI();
    }
    updateSuppliersSelectionUI() {
        const n = this.selectedSupplierIds.size;
        const elBar = document.getElementById('suppliers-selection-bar');
        const elCount = document.getElementById('suppliers-selection-bar-count');
        if (elBar) elBar.style.display = n > 0 ? 'flex' : 'none';
        if (elCount) elCount.textContent = n > 0 ? 'Đã chọn ' + n : '';
        const selectAll = document.getElementById('suppliers-select-all');
        const q = (this.suppliersSearchQuery || '').trim().toLowerCase();
        let filtered = this.demoData.suppliers || [];
        if (q) {
            const nq = this.removeAccents(q);
            filtered = filtered.filter(s => {
                const nn = this.removeAccents((s.name || '').toLowerCase());
                const p = this.removeAccents((s.phone || '').toLowerCase());
                const a = this.removeAccents((s.address || '').toLowerCase());
                const e = this.removeAccents((s.email || '').toLowerCase());
                return nn.includes(nq) || p.includes(nq) || a.includes(nq) || e.includes(nq);
            });
        }
        if (selectAll) selectAll.checked = filtered.length > 0 && filtered.every(s => this.selectedSupplierIds.has(s.id));
        document.querySelectorAll('input[data-supplier-id]').forEach(cb => {
            const id = cb.getAttribute('data-supplier-id');
            cb.checked = this.selectedSupplierIds.has(id);
        });
    }
    clearSuppliersSelection() {
        this.selectedSupplierIds.clear();
        this.updateSuppliersSelectionUI();
    }
    async bulkDeleteSuppliers() {
        if (this.selectedSupplierIds.size === 0) return;
        if (!(await confirmAsync({
            title: 'Xác nhận xóa',
            message: 'Bạn có chắc muốn xóa ' + this.selectedSupplierIds.size + ' nhà cung cấp đã chọn?',
            confirmLabel: 'Xóa',
            cancelLabel: 'Hủy',
            variant: 'danger',
        }))) return;
        this.demoData.suppliers = this.demoData.suppliers.filter(s => !this.selectedSupplierIds.has(s.id));
        this.selectedSupplierIds.clear();
        this.saveToLocalStorage();
        this.loadPage('suppliers');
        this.showNotification('Đã xóa nhà cung cấp đã chọn', 'success');
    }
    deleteSupplierById(supplierId) {
        if (!supplierId) return;
        const index = this.demoData.suppliers.findIndex(s => s.id === supplierId);
        if (index === -1) { this.showNotification('Không tìm thấy nhà cung cấp để xóa', 'error'); return; }
        this.deleteSupplier(index);
    }

