                const productId = op.id || op.productId || (prod ? prod.id : '-');
                const category = prod ? prod.category : '';
                const price = op.price != null && !isNaN(op.price) ? op.price : (prod ? prod.price : 0);
                const qty = op.quantity || 1;
                const subtotal = price * qty;
                const soldImeis = op.soldImeis && Array.isArray(op.soldImeis) ? op.soldImeis : [];
                const imeiHtml = soldImeis.length > 0 ? `<div style="font-size: 12px; color: #1d4ed8; margin-top: 4px;">IMEI: ${soldImeis.map(i => escapeHtml(i)).join(', ')}</div>` : '';
