    prefillProductInOrderForm(productId) {
        const product = (this.demoData.products || []).find(p => p.id === productId);
        if (!product) return;
        const firstRow = document.querySelector('#product-list .product-row');
        if (!firstRow) return;
        const dropdown = firstRow.querySelector('.custom-dropdown');
        const hiddenInput = firstRow.querySelector('input[name="product[]"]');
        const selectedText = dropdown?.querySelector('.selected-text');
        const priceInput = firstRow.querySelector('input[name="price[]"]');
        const quantityInput = firstRow.querySelector('input[name="quantity[]"]');
        if (hiddenInput && selectedText && priceInput) {
            hiddenInput.value = product.id;
            selectedText.textContent = product.name + ' - ' + (product.price || 0).toLocaleString('vi-VN') + ' VNĐ';
            selectedText.style.color = '#374151';
            priceInput.value = (product.price || 0).toLocaleString('vi-VN');
            if (quantityInput) quantityInput.value = 1;
            this.calculateRowTotal(priceInput);
        }
    }

