    // Xử lý export báo cáo sửa chữa
    processRepairsExport(mode) {
        const fromDate = document.getElementById('exportRepairsFromDate').value;
        const toDate = document.getElementById('exportRepairsToDate').value;

        if (!fromDate || !toDate) {
            this.showNotification('Vui lòng chọn khoảng thời gian', 'error');
            return;
        }

        if (String(fromDate) > String(toDate)) {
            this.showNotification('Ngày bắt đầu không được lớn hơn ngày kết thúc', 'error');
            return;
        }

        const filteredRepairs = (this.demoData.repairs || []).filter((rep) =>
            this.repairDateInRange(rep, fromDate, toDate)
        );

        const repairsData = filteredRepairs.map(r => ({
            id: r.id || 'SC-',
            customer: r.customerName || 'N/A',
            device: r.deviceName || '-',
            description: (r.repairDescription || '-').substring(0, 50),
            repairCost: Number(r.repairCost) || 0,
            partsManualCost: Number(r.partsManualCost) || 0,
            status: r.status || '-',
            date: r.date || '-',
            revenue: (r.status || '') === 'Đã trả' ? (Number(r.repairCost) || 0) : 0,
            profit: this.calcRepairProfit(r)
        }));

        const exportModal = document.querySelector('div[style*="position: fixed"]');
        if (exportModal) exportModal.remove();

        if (repairsData.length === 0) {
            this.showNotification('Không có phiếu sửa chữa nào trong khoảng thời gian này', 'info');
            return;
        }

        if (mode === 'view') {
            const columns = [
                { header: 'Mã phiếu', getValue: r => r.id },
                { header: 'Khách hàng', getValue: r => r.customer },
                { header: 'Thiết bị', getValue: r => r.device },
                { header: 'Mô tả lỗi', getValue: r => r.description },
                { header: 'Báo giá (VNĐ)', getValue: r => r.repairCost.toLocaleString('vi-VN') },
                { header: 'Giá linh kiện (VNĐ)', getValue: r => r.partsManualCost.toLocaleString('vi-VN') },
                { header: 'Trạng thái', getValue: r => r.status },
                { header: 'Ngày', getValue: r => r.date },
                { header: 'Doanh thu (VNĐ)', getValue: r => r.revenue.toLocaleString('vi-VN') },
                { header: 'Lợi nhuận (VNĐ)', getValue: r => r.profit.toLocaleString('vi-VN') }
            ];
            const title = `Báo cáo sửa chữa (${this.formatDateForDisplay(fromDate)} - ${this.formatDateForDisplay(toDate)})`;
            this.showDataViewer(title, repairsData, columns);
        } else if (mode === 'download') {
            const csvContent = "data:text/csv;charset=utf-8,\uFEFF" +
                `Báo cáo sửa chữa (${this.formatDateForDisplay(fromDate)} - ${this.formatDateForDisplay(toDate)})\n` +
                "Mã phiếu,Khách hàng,Thiết bị,Mô tả lỗi,Báo giá,Giá linh kiện,Trạng thái,Ngày,Doanh thu,Lợi nhuận\n" +
                repairsData.map(r =>
                    `${r.id},"${(r.customer || '').replace(/"/g, '""')}","${(r.device || '').replace(/"/g, '""')}","${(r.description || '').replace(/"/g, '""')}",${r.repairCost},${r.partsManualCost},"${r.status}","${r.date}",${r.revenue},${r.profit}`
                ).join('\n');
            const encodedUri = encodeURI(csvContent);
            const link = document.createElement("a");
            link.setAttribute("href", encodedUri);
            link.setAttribute("download", `bao_cao_sua_chua_${fromDate}_${toDate}.csv`);
            document.body.appendChild(link);
            link.click();
            document.body.removeChild(link);
            this.showNotification(`Đã tải xuống báo cáo sửa chữa (${repairsData.length} phiếu)`, 'success');
        }
    }

    // Xử lý export báo cáo doanh thu
    processSalesExport(mode) {
        const fromDate = document.getElementById('exportSalesFromDate').value;
        const toDate = document.getElementById('exportSalesToDate').value;

        if (!fromDate || !toDate) {
            this.showNotification('Vui lòng chọn khoảng thời gian', 'error');
            return;
        }

        if (String(fromDate) > String(toDate)) {
            this.showNotification('Ngày bắt đầu không được lớn hơn ngày kết thúc', 'error');
            return;
        }

        const filteredOrders = (this.demoData.orders || []).filter((order) =>
            this.orderDateInRange(order, fromDate, toDate)
        );

        const filteredRepairs = (this.demoData.repairs || []).filter((rep) =>
            this.repairDateInRange(rep, fromDate, toDate)
        );

        const calcRepairTotal = (r) => (r.status || '') === 'Đã trả' ? (Number(r.repairCost) || 0) : 0;

        // Sắp xếp và tạo dữ liệu báo cáo
        const sortedFilteredOrders = this.sortOrdersByDate(filteredOrders);
        const salesDataOrders = sortedFilteredOrders.map(order => {
            const customer = this.demoData.customers.find(c => c.id === order.customerId);
            // Sử dụng order.products thay vì order.items
            const itemCount = order.products ? order.products.length : 0;
            return {
                id: order.id,
                customer: customer ? customer.name : 'N/A',
                date: order.date,
                items: itemCount,
                total: this.getOrderRecordedNetRevenue(order),
                paymentStatus: order.paymentStatus,
                status: order.status
            };
        });

        const salesDataRepairs = filteredRepairs.map(r => ({
            id: r.id || 'SC-',
            customer: r.customerName || 'N/A',
            date: r.date,
            items: 'Sửa chữa',
            total: calcRepairTotal(r),
            paymentStatus: (r.status || '') === 'Đã trả' ? (r.paymentStatus || (r.amountPaid >= (Number(r.repairCost) || 0) ? 'Đã thanh toán' : 'Công nợ')) : '-',
            status: r.status || '-'
        }));

        const ymdKey = (d) => this.normalizeRecordDateToYmd(d) || '';
        const salesData = [...salesDataOrders, ...salesDataRepairs].sort((a, b) =>
            ymdKey(a.date).localeCompare(ymdKey(b.date))
        );

        // Đóng popup export
        const exportModal = document.querySelector('div[style*="position: fixed"]');
        if (exportModal) {
            exportModal.remove();
        }

        if (salesData.length === 0) {
            this.showNotification('Không có đơn hàng hoặc phiếu sửa chữa nào trong khoảng thời gian này', 'info');
            return;
        }

        if (mode === 'view') {
            // Hiển thị dữ liệu
            const columns = [
                { header: 'Mã đơn', getValue: sale => sale.id },
                { header: 'Khách hàng', getValue: sale => sale.customer },
                { header: 'Ngày', getValue: sale => sale.date },
                { header: 'Số sản phẩm', getValue: sale => sale.items },
                { header: 'Doanh thu ghi nhận (VNĐ)', getValue: sale => sale.total.toLocaleString('vi-VN') },
                { header: 'Thanh toán', getValue: sale => sale.paymentStatus },
                { header: 'Trạng thái', getValue: sale => sale.status }
            ];

            const title = `Báo cáo doanh thu (${this.formatDateForDisplay(fromDate)} - ${this.formatDateForDisplay(toDate)})`;
            this.showDataViewer(title, salesData, columns);

        } else if (mode === 'download') {
            // Tải xuống CSV
            const csvContent = "data:text/csv;charset=utf-8,\uFEFF" +
                `Báo cáo Doanh thu (${this.formatDateForDisplay(fromDate)} - ${this.formatDateForDisplay(toDate)})\n` +
                "Mã đơn,Khách hàng,Ngày,Số sản phẩm,Doanh thu ghi nhận,Thanh toán,Trạng thái\n" +
                salesData.map(s =>
                    `${s.id},"${s.customer}","${s.date}",${s.items},${s.total},"${s.paymentStatus}","${s.status}"`
                ).join('\n');

            const encodedUri = encodeURI(csvContent);
            const link = document.createElement("a");
            link.setAttribute("href", encodedUri);
            link.setAttribute("download", `doanh_thu_${fromDate}_${toDate}.csv`);
            document.body.appendChild(link);
            link.click();
            document.body.removeChild(link);

            this.showNotification(`Đã tải xuống báo cáo doanh thu (${salesData.length} đơn hàng)`, 'success');
        }
    }

