    // Xử lý export báo cáo Top sản phẩm
    processProductsExport(mode) {
        const fromDate = document.getElementById('exportProductsFromDate').value;
        const toDate = document.getElementById('exportProductsToDate').value;

        if (!fromDate || !toDate) {
            this.showNotification('Vui lòng chọn khoảng thời gian', 'error');
            return;
        }

        if (String(fromDate) > String(toDate)) {
            this.showNotification('Ngày bắt đầu không được lớn hơn ngày kết thúc', 'error');
            return;
        }

        const filteredOrders = (this.demoData.orders || []).filter((order) =>
            this.orderDateInRange(order, fromDate, toDate)
        );

        // Sắp xếp đơn hàng trước khi tính toán
        const sortedFilteredOrders = this.sortOrdersByDate(filteredOrders);

        // Tính toán top sản phẩm (doanh thu = sau giảm từng món + phân bổ giảm cấp đơn — khớp POS / calcOrderProfit)
        const productSales = {};
        sortedFilteredOrders.forEach(order => {
            if (!this.isOrderFinalizedForRevenue(order)) return;
            const orderItems = order.products || [];
            if (!Array.isArray(orderItems) || orderItems.length === 0) return;

            const lineNets = orderItems.map(it => this.getOrderLineNetRevenueItem(it));
            const orderDiscountAlloc = this.allocateOrderDiscountByLineWeights(lineNets, this.getEffectiveOrderLevelDiscount(order));

            orderItems.forEach((item, idx) => {
                const productId = item.id || item.productId;
                let product = this.demoData.products.find(p => p.id === productId);
                if (!product && item.name) {
                    product = this.demoData.products.find(p => (p.name || '').trim() === (item.name || '').trim());
                }
                const key = product ? product.id : productId;
                if (key == null && !item.name) return;

                if (!productSales[key]) {
                    productSales[key] = {
                        id: key,
                        name: item.name || (product ? product.name : 'N/A'),
                        price: item.price,
                        importPrice: product && (product.importPrice != null && product.importPrice !== '') ? Number(product.importPrice) : 0,
                        sold: 0,
                        revenue: 0,
                        cost: 0,
                        stock: product ? ((product.hasImei && product.imeis) ? (product.stock != null ? product.stock : product.imeis.length) : (product.stock || 0)) : 0
                    };
                }
                const quantity = item.quantity || 1;
                const lineNet = lineNets[idx];
                const alloc = orderDiscountAlloc[idx] || 0;
                const actualRevenue = Math.max(0, lineNet - alloc);
                const importPrice =
                    product && (product.importPrice != null && product.importPrice !== '') ? Number(product.importPrice) : 0;

                productSales[key].sold += quantity;
                productSales[key].revenue += actualRevenue;
                productSales[key].cost += quantity * importPrice;
            });
        });

        const topProducts = Object.values(productSales)
            .sort((a, b) => b.sold - a.sold)
            .slice(0, 10);

        // Đóng popup export
        const exportModal = document.querySelector('div[style*="position: fixed"]');
        if (exportModal) {
            exportModal.remove();
        }

        if (topProducts.length === 0) {
            this.showNotification('Không có sản phẩm nào được bán trong khoảng thời gian này', 'info');
            return;
        }

        if (mode === 'view') {
            // Hiển thị dữ liệu
            const columns = [
                { header: 'Xếp hạng', getValue: (product, index) => index + 1 },
                { header: 'Mã SP', getValue: product => product.id },
                { header: 'Tên sản phẩm', getValue: product => product.name },
                { header: 'Đã bán', getValue: product => product.sold },
                { header: 'Tồn kho', getValue: product => product.stock },
                { header: 'Doanh thu (VNĐ)', getValue: product => product.revenue.toLocaleString('vi-VN') },
                { header: 'Lợi nhuận (VNĐ)', getValue: product => (product.cost || 0) > 0 ? (product.revenue - product.cost).toLocaleString('vi-VN') : '-' }
            ];

            const title = `Top sản phẩm bán chạy (${this.formatDateForDisplay(fromDate)} - ${this.formatDateForDisplay(toDate)})`;
            this.showDataViewer(title, topProducts, columns);

        } else if (mode === 'download') {
            // Tải xuống CSV
            const csvContent = "data:text/csv;charset=utf-8,\uFEFF" +
                `Top sản phẩm bán chạy (${this.formatDateForDisplay(fromDate)} - ${this.formatDateForDisplay(toDate)})\n` +
                "Xếp hạng,Mã SP,Tên sản phẩm,Đã bán,Tồn kho,Doanh thu,Lợi nhuận\n" +
                topProducts.map((p, index) => {
                    const profit = (p.cost || 0) > 0 ? (p.revenue - p.cost) : '';
                    return `${index + 1},${p.id},"${p.name}",${p.sold},${p.stock},${p.revenue},${profit}`;
                }).join('\n');

            const encodedUri = encodeURI(csvContent);
            const link = document.createElement("a");
            link.setAttribute("href", encodedUri);
            link.setAttribute("download", `top_sanpham_${fromDate}_${toDate}.csv`);
            document.body.appendChild(link);
            link.click();
            document.body.removeChild(link);

            this.showNotification(`Đã tải xuống báo cáo top sản phẩm (${topProducts.length} sản phẩm)`, 'success');
        }
    }

