// Add notification styles to head
const styleSheet = document.createElement('style');
styleSheet.textContent = notificationStyles;
document.head.appendChild(styleSheet);

// Initialize the application (không dùng đăng nhập - dùng 1 mình)
let app;
document.getElementById('appContainer').style.display = 'flex';
app = new HamobileBanhang();
window.app = app;

window._modalMousedownTarget = null;
document.addEventListener('mousedown', function (e) { window._modalMousedownTarget = e.target; }, true);

// Global function to close modal (called from onclick)
function closeModal(element) {
    if (element) {
        element.remove();
        return;
    }
    // Try to find and remove modal by common selectors
    const modals = document.querySelectorAll('div[style*="fixed"]');
    if (modals.length > 0) {
        modals[modals.length - 1].remove(); // Remove the last modal
    }
}

// Global function for notifications
function showNotification(message, type = 'info', durationMs = 3000, longForm = false) {
    if (app) {
        app.showNotification(message, type, durationMs, longForm);
    }
}

// Mobile menu toggle function
function toggleMobileMenu() {
    const navMenu = document.getElementById('mainNavMenu');
    const overlay = document.getElementById('mobileOverlay');

    if (navMenu && overlay) {
        const isOpen = navMenu.classList.contains('mobile-open');

        if (isOpen) {
            navMenu.classList.remove('mobile-open');
            overlay.classList.remove('active');
        } else {
            navMenu.classList.add('mobile-open');
            overlay.classList.add('active');
        }
    }
}

// Đóng menu mobile khi bấm vào mục menu (dùng event delegation để chắc chắn hoạt động)
document.addEventListener('click', function (e) {
    if (e.target.closest('.nav-item') && window.innerWidth <= 768) {
        const navMenu = document.getElementById('mainNavMenu');
        const overlay = document.getElementById('mobileOverlay');
        if (navMenu && overlay) {
            navMenu.classList.remove('mobile-open');
            overlay.classList.remove('active');
        }
    }
});

// Handle window resize - close menu on larger screens
document.addEventListener('DOMContentLoaded', function () {
    window.addEventListener('popstate', function () {
        if (window.app && typeof window.app.handleOrdersMobilePopState === 'function') {
            window.app.handleOrdersMobilePopState();
        }
    });
    window.addEventListener('resize', function () {
        if (window.innerWidth > 768) {
            const navMenu = document.getElementById('mainNavMenu');
            const overlay = document.getElementById('mobileOverlay');
            if (navMenu && overlay) {
                navMenu.classList.remove('mobile-open');
                overlay.classList.remove('active');
            }
        }
    });
});
